-- ThinkHop: tables for phpMyAdmin (generated by tools/build-sql.php). The prefix is th_.

CREATE TABLE IF NOT EXISTS `th_meta` (
    `k` VARCHAR(40) NOT NULL PRIMARY KEY,
    `v` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_users` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(80) NOT NULL,
    `username` VARCHAR(20) NULL,
    `show_in_ranking` TINYINT(1) NOT NULL DEFAULT 1,
    `notify_off` VARCHAR(200) NULL,
    `notify_lang` CHAR(2) NULL,
    `email_verified_at` DATETIME NULL,
    `points_adjust` INT NOT NULL DEFAULT 0,
    `email` VARCHAR(190) NOT NULL,
    `password_hash` VARCHAR(255) NOT NULL DEFAULT '',
    `google_sub` VARCHAR(64) NULL,
    `role` TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `status` ENUM('active','disabled') NOT NULL DEFAULT 'active',
    `created_at` DATETIME NOT NULL,
    `last_login_at` DATETIME NULL,
    UNIQUE KEY `uq_email` (`email`),
    UNIQUE KEY `uq_username` (`username`),
    UNIQUE KEY `uq_google` (`google_sub`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_auth_tokens` (
    `token_hash` CHAR(64) NOT NULL PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `csrf_token` CHAR(48) NOT NULL,
    `created_at` DATETIME NOT NULL,
    `last_seen_at` DATETIME NOT NULL,
    `expires_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`),
    CONSTRAINT `fk_th_tok_user` FOREIGN KEY (`user_id`) REFERENCES `th_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_attempts` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `kind` VARCHAR(20) NOT NULL,
    `ip` VARCHAR(45) NOT NULL,
    `created_at` DATETIME NOT NULL,
    KEY `ix_kind_ip` (`kind`, `ip`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_games` (
    `user_id` INT UNSIGNED NOT NULL,
    `uid` CHAR(16) NOT NULL,
    `mode` ENUM('level','survival','daily') NOT NULL,
    `stage` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    `stars` TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `score` INT UNSIGNED NOT NULL,
    `spent` INT UNSIGNED NOT NULL DEFAULT 0,
    `correct` SMALLINT UNSIGNED NOT NULL,
    `total` SMALLINT UNSIGNED NOT NULL,
    `seconds` INT UNSIGNED NOT NULL,
    `cats` VARCHAR(400) NOT NULL DEFAULT '{}',
    `day` DATE NOT NULL,
    `played_at` DATETIME NOT NULL,
    PRIMARY KEY (`user_id`, `uid`),
    KEY `ix_user_day` (`user_id`, `day`),
    KEY `ix_played` (`played_at`),
    CONSTRAINT `fk_th_game_user` FOREIGN KEY (`user_id`) REFERENCES `th_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_questions` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `tier` ENUM('easy','medium','hard','expert') NOT NULL,
    `difficulty` DECIMAL(3,2) NOT NULL DEFAULT 0.25,
    `active` TINYINT(1) NOT NULL DEFAULT 1,
    `data` TEXT NOT NULL,
    `created_at` DATETIME NOT NULL,
    `updated_at` DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_friends` (
    `user_id` INT UNSIGNED NOT NULL,
    `friend_id` INT UNSIGNED NOT NULL,
    `created_at` DATETIME NOT NULL,
    PRIMARY KEY (`user_id`, `friend_id`),
    KEY `ix_friend` (`friend_id`),
    CONSTRAINT `fk_th_fr_user` FOREIGN KEY (`user_id`) REFERENCES `th_users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_th_fr_friend` FOREIGN KEY (`friend_id`) REFERENCES `th_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_email_tokens` (
    `token_hash` CHAR(64) NOT NULL PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `created_at` DATETIME NOT NULL,
    `expires_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`),
    CONSTRAINT `fk_th_etok_user` FOREIGN KEY (`user_id`) REFERENCES `th_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_admin_log` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `admin_id` INT UNSIGNED NULL,
    `action` VARCHAR(30) NOT NULL,
    `detail` VARCHAR(500) NOT NULL DEFAULT '{}',
    `created_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`, `created_at`),
    CONSTRAINT `fk_th_log_user` FOREIGN KEY (`user_id`) REFERENCES `th_users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_th_log_admin` FOREIGN KEY (`admin_id`) REFERENCES `th_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_push_subscriptions` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `endpoint` VARCHAR(700) NOT NULL,
    `endpoint_hash` CHAR(64) NOT NULL,
    `last_push_at` DATETIME NULL,
    `created_at` DATETIME NOT NULL,
    UNIQUE KEY `uq_endpoint` (`endpoint_hash`),
    KEY `ix_user` (`user_id`),
    CONSTRAINT `fk_th_push_user` FOREIGN KEY (`user_id`) REFERENCES `th_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_notifications` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `type` VARCHAR(20) NOT NULL,
    `day` CHAR(10) NOT NULL,
    `ref` VARCHAR(20) NOT NULL DEFAULT '',
    `data` VARCHAR(200) NOT NULL DEFAULT '{}',
    `created_at` DATETIME NOT NULL,
    `sent_at` DATETIME NULL,
    UNIQUE KEY `uq_once` (`user_id`, `type`, `day`, `ref`),
    CONSTRAINT `fk_th_note_user` FOREIGN KEY (`user_id`) REFERENCES `th_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `th_settings` (
    `k` VARCHAR(40) NOT NULL PRIMARY KEY,
    `v` TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `th_meta` (k, v) VALUES ('schema_version', '8') ON DUPLICATE KEY UPDATE v = VALUES(v);
